// Denominator is (x - d), degree 1. The numerator's degree decides the end model:
//   topdeg = 1:  (a*x + b)/(x - d)        -> HORIZONTAL asymptote y = a
//   topdeg = 2:  (a*x^2 + b*x)/(x - d)    -> SLANT asymptote y = a*x + (b + a*d)
const a = P.a, b = P.b, d = P.d, topdeg = Math.round(P.topdeg) >= 2 ? 2 : 1;
const num = (x) => (topdeg === 2 ? a * x * x + b * x : a * x + b);
const f = (x) => { const den = x - d; return Math.abs(den) < 0.04 ? NaN : num(x) / den; };
// vertical asymptote (always, at x = d)
v.line(d, -10, d, 10, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
v.fn(f, { color: H.colors.accent, width: 3 });
H.text("Horizontal vs. slant asymptotes", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
let asyText;
if (topdeg === 1) {
  // horizontal asymptote y = a
  v.line(-10, a, 10, a, { color: H.colors.accent2, width: 2.4, dash: [7, 6] });
  asyText = "deg top = deg bottom → HORIZONTAL  y = " + a.toFixed(1);
} else {
  // slant asymptote from division: y = a*x + (b + a*d)
  const m = a, k = b + a * d;
  v.fn(x => m * x + k, { color: H.colors.accent2, width: 2.4, dash: [7, 6] });
  asyText = "deg top = deg bottom + 1 → SLANT  y = " + m.toFixed(1) + "x + " + k.toFixed(1);
}
